"""Exact finite lookup construction. No randomness is generated by this module."""
from collections import Counter, defaultdict
from fractions import Fraction as F
from itertools import product
from math import lcm
from types import MappingProxyType
from dataclasses import dataclass

def exact(x):
    if isinstance(x, bool) or not isinstance(x, (int, F)):
        raise ValueError('Probability must be an exact integer or Fraction')
    return F(x)

def nat(x):
    return type(x) is int and x >= 0

@dataclass(frozen=True)
class Lookup:
    states: tuple
    outcomes: tuple
    denominator: int
    rows: object

    def step(self, state, action, seed):
        if type(seed) is not int or not 0 <= seed < self.denominator:
            raise ValueError('Seed outside finite range')
        # Missing enabled pair is rejected here. This is an external Python guard,
        # not an action-legality theorem for the total source lookup.
        return self.rows[state, action][seed]

    def cubes(self, action):
        """Three source tables indexed seed, coarse, tag. Missing pairs default 0."""
        Z = 1 + max(s[0] for s in self.states)
        M = 1 + max(s[1] for s in self.states)
        return tuple(tuple(tuple(tuple(
            self.rows[(z,k),action][u][coord] if ((z,k),action) in self.rows else 0
            for k in range(M)) for z in range(Z)) for u in range(self.denominator))
            for coord in range(3))

def compile_kernel(states, outcomes, kernels, denominator=None):
    states, outcomes = tuple(states), tuple(outcomes)
    if not states or len(set(states)) != len(states): raise ValueError('Unique nonempty states required')
    if any(not isinstance(s,tuple) or len(s)!=2 or not all(map(nat,s)) for s in states):
        raise ValueError('State codes must be natural pairs')
    if not outcomes or len(set(outcomes)) != len(outcomes) or not all(map(nat,outcomes)):
        raise ValueError('Unique nonempty natural outcomes required')
    normalized = {}
    D = 1
    for (s,a), row in kernels.items():
        if s not in states: raise ValueError('Unknown input state')
        mass = defaultdict(F)
        for o,t,p in row:
            p = exact(p)
            if o not in outcomes or t not in states or p < 0: raise ValueError('Invalid transition')
            mass[o,t] += p
        if sum(mass.values(),F()) != 1: raise ValueError('Row must have total mass one')
        normalized[s,a] = mass
        for p in mass.values(): D = lcm(D,p.denominator)
    if denominator is not None:
        if type(denominator) is not int or denominator <= 0 or denominator % D:
            raise ValueError('Seed size must be a positive multiple of all reduced denominators')
        D = denominator
    rows = {}
    for key,mass in normalized.items():
        values=[]
        for o,t in product(outcomes,states):
            n=mass[o,t]*D
            if n.denominator != 1: raise RuntimeError('Noninteger multiplicity')
            values.extend([(o,*t)]*n.numerator)
        if len(values) != D: raise RuntimeError('Bad seed table cardinality')
        rows[key]=tuple(values)
    return Lookup(states,outcomes,D,MappingProxyType(rows))

def kernel_law(kernels, state, action):
    d=defaultdict(F)
    for o,t,p in kernels[state,action]: d[(o,*t)]+=exact(p)
    return {r:p for r,p in d.items() if p}

def counting_law(lookup,state,action):
    return {r:F(n,lookup.denominator) for r,n in Counter(lookup.rows[state,action]).items()}

def history_law(kernels, start, horizon, policy):
    law={((),start):F(1)}
    for _ in range(horizon):
        nxt=defaultdict(F)
        for (h,s),p in law.items():
            a=policy(h,s)
            for r,q in kernel_law(kernels,s,a).items():
                nxt[h+((a,r),),(r[1],r[2])]+=p*q
        law=dict(nxt)
    return law

def seeded_history(lookup, start, seeds, policy):
    history=();s=start
    for u in seeds:
        a=policy(history,s);r=lookup.step(s,a,u)
        history+=((a,r),);s=(r[1],r[2])
    return history,s

def uniform_history_law(lookup,start,horizon,policy):
    law=defaultdict(F)
    for seeds in product(range(lookup.denominator),repeat=horizon):
        law[seeded_history(lookup,start,seeds,policy)]+=F(1,lookup.denominator**horizon)
    return dict(law)
